//! WP 2.4 oracle corpus: `fixtures/oracle/config-validation-corpus.jsonl`,
//! generated by `tools/oracle/module/.../ValidationCorpus.kt` through the
//! production `ConfigurationFactory.parse` (stage a) and
//! `LogicalConfigurationValidator` (stage b). Each row runs here through
//! `MarathonConfigurationLoader` and `LogicalConfigurationValidator` and is
//! compared by stage, error class, message and every cause's class (binding
//! causes carry Jackson's wording, which is ours to choose, PLAN §3.10), by
//! `to_map()` entry for entry, and, where recorded, by `serialize()` text.

#[path = "support/load.rs"]
mod load;

use marathon_config::{binding::ValidationStage, serialize};
use serde_json::Value as Json;
use std::{fs, path::Path};

fn read(name: &str) -> Vec<Json> {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../fixtures/oracle")
        .join(name);
    let text = fs::read_to_string(path).expect("corpus");
    text.lines()
        .skip(1)
        .map(|l| serde_json::from_str(l).expect("row"))
        .collect()
}

/// The macOS rows, with the Linux JDK's rows swapped in by `id` on Linux
/// (`canonicalFile` throws there for a symlink loop mid-path; `paths.rs`).
fn rows() -> Vec<Json> {
    let mut rows = read("coverage-c95b2128/config-validation-corpus.jsonl");
    if cfg!(target_os = "linux") {
        let linux = read("config-validation-corpus-linux.jsonl");
        assert_eq!(linux.len(), 3);
        for row in linux {
            let slot = rows.iter_mut().find(|r| r["id"] == row["id"]).expect("linux row id");
            *slot = row;
        }
    }
    rows
}

/// The generator's `@<hash>` normalisation: an `@` and up to eight hex
/// digits right after a class-name character, ending the token.
fn normalize_hashes(s: &str) -> String {
    let chars: Vec<char> = s.chars().collect();
    let mut out = String::new();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '@' && i > 0 && (chars[i - 1].is_ascii_alphanumeric() || matches!(chars[i - 1], '_' | '$')) {
            let digits = chars[i + 1..]
                .iter()
                .take_while(|c| c.is_ascii_hexdigit() && !c.is_ascii_uppercase())
                .count();
            let next = chars.get(i + 1 + digits);
            if (1..=8).contains(&digits) && !next.is_some_and(|c| c.is_ascii_alphanumeric()) {
                out.push_str("@<hash>");
                i += 1 + digits;
                continue;
            }
        }
        out.push(chars[i]);
        i += 1;
    }
    out
}

struct Cleaner {
    dir: String,
    home: Option<String>,
}
impl Cleaner {
    fn clean(&self, s: &str) -> String {
        let mut s = s.replace(&self.dir, "$DIR");
        if let Some(home) = &self.home {
            s = s.replace(home, "/home/");
        }
        normalize_hashes(&s)
    }
    fn java(&self, s: &str) -> String {
        self.clean(&s.to_owned())
    }
}

#[test]
fn validation_corpus_matches_jvm() {
    let home = fs::canonicalize("/home")
        .ok()
        .map(|p| format!("{}/", p.to_string_lossy()))
        .filter(|h| h != "/home/");
    let mut failures = Vec::new();
    let rows = rows();
    assert_eq!(rows.len(), 87);
    for row in &rows {
        let id = row["id"].as_str().unwrap();
        let (_tmp, dir) = load::temp().unwrap();
        let (file, marathonfile_dir) = if row["kind"] == "case" {
            load::copy_dir(
                &load::fixture_config().join("ios/derivedDataDir"),
                &dir.join("derivedDataDir"),
            )
            .unwrap();
            fs::write(dir.join("app.apk"), "").unwrap();
            fs::create_dir(dir.join("apkdir")).unwrap();
            fs::write(dir.join("known_hosts"), "").unwrap();
            std::os::unix::fs::symlink(dir.join("loop"), dir.join("loop")).unwrap();
            let file = dir.join("Marathonfile");
            let input = row["input"].as_str().unwrap().replace("@DIR@", &dir.to_string_lossy());
            fs::write(&file, format!("{input}\n")).unwrap();
            (file, dir.clone())
        } else {
            load::copy_dir(&load::fixture_config(), &dir).unwrap();
            let file = dir.join(row["input"].as_str().unwrap());
            let parent = file.parent().unwrap().to_path_buf();
            (file, parent)
        };
        let cleaner = Cleaner {
            dir: dir.to_string_lossy().into_owned(),
            home: home.clone(),
        };
        let sdk = (!row["noSdk"].as_bool().unwrap()).then_some("/android-sdk");
        let mut context = load::context(&file, &marathonfile_dir, sdk);
        // The generator's substitutor knows exactly this cycle.
        context.environment.push(("A".into(), "${B}".into()));
        context.environment.push(("B".into(), "${A}".into()));
        let parsed = load::parse(&file, &context);
        let (stage, error) = match &parsed {
            Err(e) => {
                assert_eq!(e.stage, ValidationStage::Parse, "{id}");
                ("parse", Some(e.as_ref().clone()))
            }
            Ok(config) => match load::validate(config) {
                Err(e) => {
                    assert_eq!(e.stage, ValidationStage::Logical, "{id}");
                    ("logical", Some(*e))
                }
                Ok(()) => ("ok", None),
            },
        };
        if stage != row["stage"] {
            failures.push(format!("{id}: stage {stage} vs {}: {error:?}", row["stage"]));
            continue;
        }
        if let Some(e) = &error {
            let expected = &row["error"];
            let got = (cleaner.java(&e.class), e.message.as_ref().map(|m| cleaner.java(m)));
            let want = (
                expected["class"].as_str().unwrap().to_owned(),
                expected["message"].as_str().map(str::to_owned),
            );
            if got != want {
                failures.push(format!("{id}: error {got:?} vs {want:?}"));
            }
            let want_causes: Vec<String> = expected["causes"]
                .as_array()
                .unwrap()
                .iter()
                .map(|c| c.as_str().unwrap().split(':').next().unwrap().to_owned())
                .collect();
            let got_causes: Vec<String> = e.causes.iter().map(|c| c.class.to_owned()).collect();
            if got_causes != want_causes {
                failures.push(format!("{id}: causes {got_causes:?} vs {want_causes:?}"));
            }
        }
        let Ok(config) = &parsed else { continue };
        let got: Vec<(String, String)> = config
            .to_map(&context.process_dir)
            .iter()
            .map(|(k, v)| (k.to_owned(), cleaner.java(v)))
            .collect();
        let want: Vec<(String, String)> = row["toMap"]
            .as_array()
            .unwrap()
            .iter()
            .map(|pair| {
                let key = pair[0].as_str().unwrap().to_owned();
                let mut value = pair[1].as_str().unwrap().to_owned();
                // D9 (WP 2.2 S4 narrowed): a null filter `values` element is
                // dropped at bind, so Rust cannot show the `null` Kotlin prints.
                if id == "m-filter-null-value" && key == "filtering" {
                    value = value.replace("[a, null, b]", "[a, b]");
                }
                (key, value)
            })
            .collect();
        if got != want {
            for (g, w) in got.iter().zip(&want) {
                if g != w {
                    failures.push(format!("{id}: toMap {}\n  got  {}\n  want {}", w.0, g.1, w.1));
                }
            }
            if got.len() != want.len() {
                failures.push(format!("{id}: toMap has {} entries, want {}", got.len(), want.len()));
            }
        }
        if let Some(want) = row["serialized"].as_str() {
            // D6 (WP 2.3a decision 7): Kotlin writes the default nm pattern,
            // whose lookahead the regex crate cannot compile; omitting the key
            // rebinds the same default. Otherwise the text is Jackson's.
            let want = want.replace("\n    testClassRegexes:\n    - \"^((?!Abstract).)*Test[s]*$\"", "");
            let got = cleaner.java(&serialize(config));
            if got != want {
                failures.push(format!("{id}: serialized\n--- got\n{got}\n--- want\n{want}"));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} failures:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
